def all_rects(g):
    H,W=g.shape
    rects=[]
    for c in range(10):
        m=(g==c).astype(int)
        # for each top-left, for each width, max height via histogram method
        for y in range(H):
            for x in range(W):
                if not m[y,x]: continue
                wmax=0
                while x+wmax<W and m[y,x+wmax]: wmax+=1
                for w in range(3,wmax+1):
                    h=1
                    while y+h<H and m[y:y+h, x:x+w].sum()==h*w:
                        h+=1
                    if h>=3:
                        rects.append((y,y+h-1,x,x+w-1,h,w,c))
    # keep maximal (not contained)
    maximal=[]
    for r in rects:
        contained=any(r!=s and r[0]>=s[0] and r[1]<=s[1] and r[2]>=s[2] and r[3]<=s[3] for s in rects)
        if not contained: maximal.append(r)
    return sorted(set(maximal))

